changeSet.sql:
-- The ONE place the four values are written. True when it altered the leaf, false when the leaf already carried all
-- four. Only an ordinary table takes storage parameters: a partitioned parent or model partition is refused by name
-- rather than by PostgreSQL's own error. The comparison is on the exact stored text (reloptions keeps what was typed).
CREATE OR REPLACE FUNCTION nexus.partition_set_leaf_autovacuum(p_leaf regclass)
RETURNS boolean
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_ns   text;
    v_name text;
    v_kind "char";
    v_opts text[];
BEGIN
    SELECT n.nspname::text, c.relname::text, c.relkind, c.reloptions
      INTO v_ns, v_name, v_kind, v_opts
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_leaf;
    IF v_kind IS DISTINCT FROM 'r' THEN
        RAISE EXCEPTION 'nexus.partition_set_leaf_autovacuum: % is not an ordinary table (a partitioned table takes no storage parameters)', p_leaf
            USING ERRCODE = 'wrong_object_type';
    END IF;
    IF COALESCE(v_opts, ARRAY[]::text[]) @> ARRAY[
           'autovacuum_vacuum_scale_factor=0.05',
           'autovacuum_vacuum_threshold=1000',
           'autovacuum_vacuum_insert_scale_factor=0.05',
           'autovacuum_analyze_scale_factor=0.02']::text[] THEN
        RETURN false;
    END IF;
    EXECUTE pg_catalog.format(
        'ALTER TABLE %I.%I SET (autovacuum_vacuum_scale_factor = 0.05, autovacuum_vacuum_threshold = 1000, '
        'autovacuum_vacuum_insert_scale_factor = 0.05, autovacuum_analyze_scale_factor = 0.02)',
        v_ns, v_name);
    RETURN true;
END
$fn$;

-- EXECUTE stays with PUBLIC, unlike the other partition helpers, on purpose: the function runs with its caller's
-- rights and ALTER TABLE needs ownership of the leaf, so a role that does not own the leaf (nexus_svc, nexus_diag)
-- is refused by PostgreSQL itself, and the runAlways self-heal must be able to call it when the migrating role
-- does not own the function (a cluster whose functions were created by a superuser: Catalog013RlsReplayTest).

-- vectors-030-1's body, plus the call after the access mirror. A parent whose name minus a trailing _new is
-- chunks (the walk's chunks_new included); taxonomy_centroids leaves are left at PostgreSQL's defaults.
CREATE OR REPLACE FUNCTION nexus.partition_ensure_leaf(p_parent regclass, p_model_part regclass, p_tenant text, p_force boolean)
RETURNS boolean
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_ns          text;
    v_parent_name text;
    v_mp_name     text;
    v_model       text;
    v_leaf        text;
    v_leaf_oid    regclass;
    v_taken       record;
BEGIN
    SELECT n.nspname::text, c.relname::text INTO v_ns, v_mp_name
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_model_part;
    SELECT c.relname::text INTO v_parent_name FROM pg_catalog.pg_class c WHERE c.oid = p_parent;
    v_model := nexus.partition_bound_value(p_model_part);
    IF v_model IS NULL THEN
        RAISE EXCEPTION 'nexus.partition_ensure_leaf: % has no single-value LIST bound', p_model_part
            USING ERRCODE = 'wrong_object_type';
    END IF;

    -- The existence check: by bound, never by name.
    PERFORM 1
       FROM pg_catalog.pg_inherits i
      WHERE i.inhparent = p_model_part
        AND nexus.partition_bound_value(i.inhrelid) = p_tenant;
    IF FOUND THEN
        RETURN false;
    END IF;

    v_leaf := nexus.partition_name(v_parent_name, v_model, p_tenant);
    SELECT c.relkind, c.relispartition, pg_catalog.pg_get_expr(c.relpartbound, c.oid) AS bound
      INTO v_taken
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = v_ns AND c.relname = v_leaf;
    IF FOUND THEN
        RAISE EXCEPTION 'nexus partition name collision: %.% already exists and is not the leaf of % under %',
            v_ns, v_leaf, p_tenant, v_mp_name
            USING ERRCODE = 'duplicate_table',
                  DETAIL = pg_catalog.format('relkind %s, partition %s, bound %s',
                                             v_taken.relkind, v_taken.relispartition, COALESCE(v_taken.bound, 'none')),
                  HINT = 'Two tenants hash to one leaf name, or an unrelated relation holds it. The creation is refused.';
    END IF;

    EXECUTE pg_catalog.format('CREATE TABLE %I.%I PARTITION OF %I.%I FOR VALUES IN (%L)',
                              v_ns, v_leaf, v_ns, v_mp_name, p_tenant);
    v_leaf_oid := (pg_catalog.quote_ident(v_ns) || '.' || pg_catalog.quote_ident(v_leaf))::pg_catalog.regclass;
    PERFORM nexus.partition_copy_access(p_parent, v_leaf_oid, p_force);
    IF pg_catalog.regexp_replace(v_parent_name, '_new$', '') = 'chunks' THEN
        PERFORM nexus.partition_set_leaf_autovacuum(v_leaf_oid);
    END IF;
    RETURN true;
END
$fn$;

rollback.sql:
-- vectors-030-1's partition_ensure_leaf, verbatim, then the helper goes. Leaves keep the reloptions they carry
-- (harmless); the vectors-034-2 rollback clears them.
CREATE OR REPLACE FUNCTION nexus.partition_ensure_leaf(p_parent regclass, p_model_part regclass, p_tenant text, p_force boolean)
RETURNS boolean
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_ns          text;
    v_parent_name text;
    v_mp_name     text;
    v_model       text;
    v_leaf        text;
    v_taken       record;
BEGIN
    SELECT n.nspname::text, c.relname::text INTO v_ns, v_mp_name
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_model_part;
    SELECT c.relname::text INTO v_parent_name FROM pg_catalog.pg_class c WHERE c.oid = p_parent;
    v_model := nexus.partition_bound_value(p_model_part);
    IF v_model IS NULL THEN
        RAISE EXCEPTION 'nexus.partition_ensure_leaf: % has no single-value LIST bound', p_model_part
            USING ERRCODE = 'wrong_object_type';
    END IF;

    -- The existence check: by bound, never by name.
    PERFORM 1
       FROM pg_catalog.pg_inherits i
      WHERE i.inhparent = p_model_part
        AND nexus.partition_bound_value(i.inhrelid) = p_tenant;
    IF FOUND THEN
        RETURN false;
    END IF;

    v_leaf := nexus.partition_name(v_parent_name, v_model, p_tenant);
    SELECT c.relkind, c.relispartition, pg_catalog.pg_get_expr(c.relpartbound, c.oid) AS bound
      INTO v_taken
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = v_ns AND c.relname = v_leaf;
    IF FOUND THEN
        RAISE EXCEPTION 'nexus partition name collision: %.% already exists and is not the leaf of % under %',
            v_ns, v_leaf, p_tenant, v_mp_name
            USING ERRCODE = 'duplicate_table',
                  DETAIL = pg_catalog.format('relkind %s, partition %s, bound %s',
                                             v_taken.relkind, v_taken.relispartition, COALESCE(v_taken.bound, 'none')),
                  HINT = 'Two tenants hash to one leaf name, or an unrelated relation holds it. The creation is refused.';
    END IF;

    EXECUTE pg_catalog.format('CREATE TABLE %I.%I PARTITION OF %I.%I FOR VALUES IN (%L)',
                              v_ns, v_leaf, v_ns, v_mp_name, p_tenant);
    PERFORM nexus.partition_copy_access(p_parent,
        (pg_catalog.quote_ident(v_ns) || '.' || pg_catalog.quote_ident(v_leaf))::pg_catalog.regclass,
        p_force);
    RETURN true;
END
$fn$;

DROP FUNCTION IF EXISTS nexus.partition_set_leaf_autovacuum(regclass);

changeSet.sql:
DO $$
DECLARE
    r         record;
    v_seen    integer := 0;
    v_altered integer := 0;
    v_ok      integer := 0;
    v_busy    integer := 0;
    v_gone    integer := 0;
    v_foreign integer := 0;
    -- The same four texts as vectors-034-1's helper compares against; keep the two in step.
    v_four    text[] := ARRAY[
        'autovacuum_vacuum_scale_factor=0.05',
        'autovacuum_vacuum_threshold=1000',
        'autovacuum_vacuum_insert_scale_factor=0.05',
        'autovacuum_analyze_scale_factor=0.02']::text[];
BEGIN
    -- Bound the wait per leaf: a running VACUUM or CREATE INDEX CONCURRENTLY holds SHARE UPDATE EXCLUSIVE.
    SET LOCAL lock_timeout = '5s';
    -- Level 0 is the parent itself; the leaves are the rows with isleaf (an ordinary table, relkind r).
    FOR r IN
        SELECT t.relid::regclass AS leaf, c.relowner, c.reloptions
          FROM pg_partition_tree('nexus.chunks'::regclass) t
          JOIN pg_class c ON c.oid = t.relid
         WHERE t.level > 0 AND t.isleaf AND c.relkind = 'r'
         ORDER BY t.relid::regclass::text
    LOOP
        v_seen := v_seen + 1;
        -- Already correct comes first: it needs no lock and no ownership, so a leaf owned by another role that
        -- already carries the four is not reported (and not warned about) on every boot.
        IF COALESCE(r.reloptions, ARRAY[]::text[]) @> v_four THEN
            v_ok := v_ok + 1;
            CONTINUE;
        END IF;
        IF NOT pg_has_role(r.relowner, 'USAGE') THEN
            v_foreign := v_foreign + 1;
            RAISE WARNING 'vectors-034-2: % is owned by a role % is not a member of, its autovacuum reloptions are left as they are', r.leaf, current_user;
            CONTINUE;
        END IF;
        BEGIN
            IF nexus.partition_set_leaf_autovacuum(r.leaf) THEN
                v_altered := v_altered + 1;
            ELSE
                v_ok := v_ok + 1;
            END IF;
        EXCEPTION
            -- lock_not_available: the 5 s lock_timeout. deadlock_detected: a CREATE INDEX CONCURRENTLY that holds
            -- SHARE UPDATE EXCLUSIVE on the leaf waits for this transaction (WaitForOlderSnapshots) while this
            -- transaction waits for the leaf; the 1 s deadlock_timeout fires before the 5 s lock_timeout and
            -- PostgreSQL aborts one side. Either way the leaf is left for the next boot.
            WHEN lock_not_available OR deadlock_detected THEN
                v_busy := v_busy + 1;
                RAISE WARNING 'vectors-034-2: % is locked by another session, its autovacuum reloptions are set on the next boot (%: %)', r.leaf, SQLSTATE, SQLERRM;
            -- A guard for a leaf that vanishes between the partition-tree scan and the helper (the helper's own check
            -- says wrong_object_type for a vanished oid, the ALTER says undefined_table once a lock wait ends). The
            -- scan's AccessShareLock on every leaf, held to the end of this transaction, makes a committed DROP
            -- impossible meanwhile: a concurrent DROP waits and, if it holds the leaf, ends in deadlock_detected above.
            WHEN undefined_table OR wrong_object_type THEN
                v_gone := v_gone + 1;
                RAISE WARNING 'vectors-034-2: a chunks leaf vanished during the self-heal (oid %), nothing to set (%: %)', r.leaf, SQLSTATE, SQLERRM;
        END;
    END LOOP;
    IF v_seen = 0 THEN
        RAISE WARNING 'vectors-034-2: nexus.chunks has no leaf partition; the RDR-225 walk always leaves one per model for the default tenant';
    END IF;
    RAISE NOTICE 'vectors-034-2: nexus.chunks leaves examined %, altered %, already correct %, locked %, vanished %, foreign-owned %',
        v_seen, v_altered, v_ok, v_busy, v_gone, v_foreign;
END
$$;
